void Screen1ViewBase::buttonCallbackHandler(const touchgfx::AbstractButton& src)
{
    if (&src == &theme_button)
    {
        //themeChange
        //When theme_button clicked change screen to Screen2
        //Go to Screen2 with screen transition towards West
        application().gotoScreen2ScreenWipeTransitionWest();
    }
    if (&src == &settings_button)
    {
        //settings
        //When settings_button clicked change screen to Screen3
        //Go to Screen3 with screen transition towards South
        application().gotoScreen3ScreenCoverTransitionSouth();
    }
    if (&src == &tcTriggerButton)
    {
        //tcTRIGGER
        //When tcTriggerButton clicked fade tcInactive
        //Fade tcInactive to alpha:0 with QuadIn easing in 250 ms (15 Ticks)
        tcInactive.clearFadeAnimationEndedAction();
        tcInactive.startFadeAnimation(0, 15, touchgfx::EasingEquations::quadEaseIn);
        tcInactive.setFadeAnimationEndedAction(tcTRIGGEREndedCallback);
    }
    if (&src == &voltageTriggerButton)
    {
        //voltageTRIGGER
        //When voltageTriggerButton clicked fade voltageInactive
        //Fade voltageInactive to alpha:0 with QuadIn easing in 250 ms (15 Ticks)
        voltageInactive.clearFadeAnimationEndedAction();
        voltageInactive.startFadeAnimation(0, 15, touchgfx::EasingEquations::quadEaseIn);
        voltageInactive.setFadeAnimationEndedAction(voltageTRIGGEREndedCallback);
    }
    if (&src == &tempTriggerButton)
    {
        //tempTRIGGER
        //When tempTriggerButton clicked fade tempInactive
        //Fade tempInactive to alpha:0 with QuadIn easing in 250 ms (15 Ticks)
        tempInactive.clearFadeAnimationEndedAction();
        tempInactive.startFadeAnimation(0, 15, touchgfx::EasingEquations::quadEaseIn);
        tempInactive.setFadeAnimationEndedAction(tempTRIGGEREndedCallback);
    }
}

